<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Factories\HasFactory; use Illuminate\Database\Eloquent\Relations\HasMany; use Illuminate\Foundation\Auth\User as Authenticatable; use Illuminate\Notifications\Notifiable;
class User extends Authenticatable { use HasFactory, Notifiable; protected $fillable=['name','email','password','phone','role','currency','language','theme']; protected $hidden=['password','remember_token']; protected function casts():array{return ['email_verified_at'=>'datetime','password'=>'hashed'];} public function categories():HasMany{return $this->hasMany(Category::class);} public function paymentMethods():HasMany{return $this->hasMany(PaymentMethod::class);} public function incomeSources():HasMany{return $this->hasMany(IncomeSource::class);} public function incomes():HasMany{return $this->hasMany(Income::class);} public function expenses():HasMany{return $this->hasMany(Expense::class);} public function budgets():HasMany{return $this->hasMany(Budget::class);} public function savingsGoals():HasMany{return $this->hasMany(SavingsGoal::class);} public function recurringTransactions():HasMany{return $this->hasMany(RecurringTransaction::class);} public function financialNotifications():HasMany{return $this->hasMany(Notification::class);} public function activityLogs():HasMany{return $this->hasMany(ActivityLog::class);} public function attachments():HasMany{return $this->hasMany(Attachment::class);} public function settings():HasMany{return $this->hasMany(Setting::class);} }
